1	<!doctype html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Relay Pricing</title>
7	<style>
8	  * { box-sizing: border-box }
9	  body { margin: 0; font-family: system-ui, sans-serif; background: #ffffff; color: #24292f }
10	  header { padding: 20px 32px; border-bottom: 1px solid #e8eaee; font-weight: 700 }
11	  main { max-width: 720px; margin: 40px auto; padding: 0 24px }
12	  h1 { font-size: 28px; margin: 0 0 6px }
13	  p.sub { color: #5a6470; margin: 0 0 32px; font-size: 15px; line-height: 1.6 }
14	  .card { border: 1px solid #e8eaee; border-radius: 12px; padding: 28px; max-width: 380px }
15	  .plan { font-size: 13px; letter-spacing: 0.08em; text-transform: uppercase; color: #667178 }
16	  .price { font-size: 34px; font-weight: 700; margin: 10px 0 }
17	  .price small { font-size: 14px; font-weight: 400; color: #667178 }
18	  ul { padding-left: 18px; margin: 0 0 24px; color: #4d5561; font-size: 14px; line-height: 1.9 }
19	  a.more { color: #0062cc; font-size: 14px; text-decoration: underline }
20	  a.more:focus-visible { outline: 2px solid #0062cc; outline-offset: 2px }
21	  a.more:hover { text-decoration-thickness: 2px }
22	  button { width: 100%; padding: 12px; background: #86a9ef; color: #ffffff; border: 0; border-radius: 8px; font-size: 15px; font-weight: 600; cursor: pointer; margin-bottom: 14px }
23	  button:hover { background: #6b92d9 }
24	  button:active { background: #5b80c7 }
25	  button:focus-visible { outline: 2px solid #024bb5; outline-offset: 2px }
26	  .note { font-size: 12px; color: #667178; margin-top: 20px }
27	</style>
28	<script>
29	  window.__activated = []
30	  document.addEventListener('click', function (e) {
31	    var hit = e.target instanceof Element ? e.target.closest('[data-track]') : null
32	    var name = hit ? hit.getAttribute('data-track') : null
33	    if (name) window.__activated.push(name)
34	  })
35	</script>
36	</head>
37	<body>
38	<header>Relay</header>
39	<main>
40	  <h1>Simple pricing</h1>
41	  <p class="sub">One plan, every feature, cancel whenever you like. No usage tiers and no per-seat surprises at the end of the month.</p>
42	  <div class="card">
43	    <div class="plan">Team</div>
44	    <div class="price">$24 <small>per member, per month</small></div>
45	    <ul>
46	      <li>Unlimited shared inboxes</li>
47	      <li>Automations and scheduled sends</li>
48	      <li>Priority support within one business day</li>
49	    </ul>
50	    <button type="button" data-track="cta">Start free trial</button>
51	    <a class="more" href="#details" data-track="learn-more">See what is included</a>
52	  </div>
53	  <p class="note" id="details">Prices exclude VAT. Annual billing saves two months.</p>
54	</main>
55	</body>
56	</html>
